<?php
session_start(); require __DIR__.'/config.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$message=''; $error='';
try{$tables=db()->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN); $required=['users','admins','organisations','clients','projects','tasks','tickets','events']; $missing=array_values(array_diff($required,$tables));}catch(Throwable $e){$missing=[];$error='Database connection failed: '. $e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST' && !$error){$key=$_POST['key']??''; if(!hash_equals('change-me-before-launch',$key)){$error='Invalid setup key. Edit setup.php before using it.';}else{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)$error='Use a name, valid email, and password of at least 10 characters.';else{try{$s=db()->prepare("INSERT INTO admins(first_name,last_name,name,email,password,active,created_at,updated_at) VALUES(?,?,?,?,?,1,NOW(),NOW())");$parts=preg_split('/\s+/',$name,2);$s->execute([$parts[0],$parts[1]??'', $name,$email,password_hash($pass,PASSWORD_BCRYPT)]);$message='Administrator created. Delete setup.php now, then sign in.';}catch(Throwable $e){$error=$e->getMessage();}}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup · C’est Bon</title><link rel="stylesheet" href="style.css"></head><body class="login"><div class="login-card"><div class="brand">C’est Bon<span>Portal setup</span></div><?php if($message):?><div class="success"><?=h($message)?></div><?php elseif($error):?><div class="error"><?=h($error)?></div><?php endif;?><p class="muted">Database tables found: <?=count($tables??[])?><?php if($missing):?> · Missing: <?=h(implode(', ',$missing))?><?php endif;?></p><form method="post"><label>Setup key<input name="key" required></label><label>Administrator name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" required></label><button class="btn full">Create administrator</button></form><p class="muted small">After setup, remove this setup.php file from the server.</p></div></body></html>
